python3 - <<'PYEOF'
import json, re
d = json.load(open('work/rewrite.json'))
desc, readme = d['description'], d['readme']
errs = []
L = len(desc)
if not (60 <= L <= 120): errs.append(f"description length {L}")
hs = re.findall(r'^## (.+)$', readme, flags=re.M)
expected = ["Summary","Key features","Usage","Use cases","Limitations","Metadata"]
if hs != expected: errs.append(f"headings wrong: {hs}")
for k in d['keywords']:
    if k in desc: print(f"keyword OK in description: {k}")
    elif k in readme: print(f"keyword OK in readme: {k}")
    else: errs.append(f"keyword missing: {k}")
ps = d['starter_prompts']
if not (2 <= len(ps) <= 4): errs.append(f"prompt count {len(ps)}")
for p in ps:
    if not p.endswith('?'): errs.append(f"not a question: {p}")
for name, v in d.items():
    if '```' in str(v): errs.append(f"triple backticks in {name}")
usage = readme.split('## Usage')[1].split('## Use cases')[0]
for line in usage.splitlines():
    if line.strip().startswith(('User:', 'Grant Finder:')):
        if not (line.startswith('    ') and not line.startswith('     ')):
            errs.append(f"bad indent: {line[:40]!r}")
        else:
            print(f"indent OK: {line.strip()[:60]}")
body = '\n'.join(l for l in readme.splitlines() if not l.startswith('#'))
print("prose chars outside headings:", len(re.sub(r'^[-*] ', '', body, flags=re.M)))
print("description chars:", L)
print("ERRORS:" if errs else "ALL CHECKS PASSED")
for e in errs: print(" -", e)
